import fs from 'node:fs';import crypto from 'node:crypto';import{presentDialogue}from '../engine2/dialogue-presentation.js';
const m=JSON.parse(fs.readFileSync(new URL('../animation-expansion/story/story_manifest.json',import.meta.url))),recordings=JSON.parse(fs.readFileSync(new URL('../engine2/voices/manifest.json',import.meta.url))),cast={Sable:'Brodie',Mara:'Miriam',Rook:'Elliot',Iona:'Ella',Mira:'Maya',Brass:'Bernard',Riven:'Kirk',Veyr:'Benjamin',Nell:'Rachel',Hesper:'Marlene',Corin:'Elias',Father:'Clint',Dara:'Sandra',Choir:'Xylar','The Choir':'Xylar','Wiremother':'Wanda','Lark':'Rachel','Tilly':'Pip','Boy':'Pip','Girl':'Rachel','Hollow Crown':'Monster','Mute Giant':'Ragnar','First Form':'Xylar','Glass Child':'Serene','Echo':'Serene','Chainmaster':'Kirk','Redactor':'Malachi','False Judge':'Tom','Choir Hand':'Grungle','Choir Lung':'Monster','Sky Marshal':'Clint','Star Reader':'Eleanor','Tollkeeper':'Clint','Wind Bailiff':'Arjun','Silt Crown':'Monster','Homekeeper':'Eleanor','Oren':'James','Worker':'Martin','Foreman':'Kirk','Engineer':'Elliot','Clerk':'Leslie','Potter':'Mabel','Pilot':'James','Gardener':'Mabel','Surveyor':'Benjamin','Survivor':'Sandra','Deserter':'Clint','Diver':'Martin','Observer':'Eleanor','Mender':'Serene'};
const lines=new Map();for(const r of m.text_records){for(const turn of presentDialogue(r.text_verbatim).voiceSegments){const key=turn.speaker+'\0'+turn.text,id=crypto.createHash('sha256').update(key).digest('hex').slice(0,20);if(!lines.has(key))lines.set(key,{id,speaker:turn.speaker,text:turn.text,suggested_voice:cast[turn.speaker]||'Leslie',delivery:'Conversational, specific to the scene. Stage direction is metadata and must not be read aloud.',source_records:[],audio:recordings.lines.find(l=>l.speaker===turn.speaker&&l.text===turn.text)?.audio||null});lines.get(key).source_records.push({record_id:r.id,chapter:r.chapter,scene:r.scene,field:r.field,provenance:r.provenance});}}
const all=[...lines.values()],out={schema:'ash-aether.voice-script/1',status:'rewritten script; partial recorded coverage',unique_spoken_turns:all.length,recorded_turns:all.filter(l=>l.audio).length,text_characters:all.reduce((n,l)=>n+l.text.length,0),rules:['Never voice inventory, controls or choice buttons','Match exact speaker and text','Keep branch alternatives separate','No celebrity or personal voice cloning'],lines:all};fs.writeFileSync(new URL('./voice-script.json',import.meta.url),JSON.stringify(out,null,2));console.log(JSON.stringify({spoken_turns:out.unique_spoken_turns,recorded:out.recorded_turns,characters:out.text_characters}));
